using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.CRM;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views;
public partial class CrmWindow:Window{readonly Usuario _u;readonly ErpDbContext _db=new();public CrmWindow(Usuario u){InitializeComponent();_u=u;Loaded+=async(_,__)=>await Atualizar();}async Task Atualizar(){OportunidadesGrid.ItemsSource=await _db.OportunidadesCrm.Include(x=>x.Cliente).OrderByDescending(x=>x.Id).ToListAsync();InativosGrid.ItemsSource=await new CrmService(_db).ClientesInativosAsync(90);PerdidasGrid.ItemsSource=await _db.VendasPerdidas.Include(x=>x.Cliente).Include(x=>x.Produto).OrderByDescending(x=>x.Data).ToListAsync();}async void Nova_Click(object s,RoutedEventArgs e){var d=new NovaOportunidadeWindow(_u){Owner=this};if(d.ShowDialog()==true)await Atualizar();}}